/**
 * JSON endpoints of the WebAuthn ceremonies started by the browser.
 *
 * <p>
 * Registration adds a passkey to the account of the session open in the tenant: the user comes from
 * the {@code AUTH_SESSION_ID} cookie, never from the request body, so nobody can add a key to
 * another account. Authentication only hands out a challenge; the signed answer is posted to the
 * authorize form ({@code step=webauthn-login}), which opens the session.
 * </p>
 */
@Slf4j
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class WebAuthnController {

  private final SessionManager sessionManager;
  private final WebAuthnRelyingParty relyingParty;
  private final BeginRegistrationUsecase beginRegistration;
  private final FinishRegistrationUsecase finishRegistration;
  private final BeginAuthenticationUsecase beginAuthentication;

  @POST
  @Path("oauth/openid/{tenant}/webauthn/register/begin")
  @Consumes(MediaType.APPLICATION_JSON)
  @Produces(MediaType.APPLICATION_JSON)
  public Response registerBegin(final @PathParam("tenant") String tenant,
      final @CookieParam(OidcCookieManager.AUTH_SESSION_ID) String cookie) {
    Optional<SessionInfo> session = sessionManager.loadSession(cookie, tenant);
    if (session.isEmpty()) {
      return unauthorized();
    }
    try {
      var rp = relyingParty.resolve(tenant);
      return Response
          .ok(beginRegistration.begin(session.get().getUserId(), tenant, rp.id(), rp.name()))
          .build();
    } catch (WebAuthnException | IllegalArgumentException ex) {
      return badRequest(ex);
    }
  }

  @POST
  @Path("oauth/openid/{tenant}/webauthn/register/finish")
  @Consumes(MediaType.APPLICATION_JSON)
  @Produces(MediaType.APPLICATION_JSON)
  public Response registerFinish(final @PathParam("tenant") String tenant,
      final @CookieParam(OidcCookieManager.AUTH_SESSION_ID) String cookie,
      final Map<String, Object> body) {
    Optional<SessionInfo> session = sessionManager.loadSession(cookie, tenant);
    if (session.isEmpty()) {
      return unauthorized();
    }
    Map<String, Object> payload = body == null ? Map.of() : body;
    try {
      var rp = relyingParty.resolve(tenant);
      finishRegistration.finish(str(payload.get("challengeId")), tenant, session.get().getUserId(),
          credential(payload), rp.origin(), rp.id(), str(payload.get("deviceName")));
      return Response.ok(Map.of("status", "ok")).build();
    } catch (WebAuthnException | IllegalArgumentException ex) {
      return badRequest(ex);
    }
  }

  @POST
  @Path("oauth/openid/{tenant}/webauthn/authenticate/begin")
  @Produces(MediaType.APPLICATION_JSON)
  public Response authenticateBegin(final @PathParam("tenant") String tenant) {
    try {
      return Response.ok(beginAuthentication.begin(tenant, relyingParty.resolve(tenant).id()))
          .build();
    } catch (WebAuthnException | IllegalArgumentException ex) {
      return badRequest(ex);
    }
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> credential(Map<String, Object> body) {
    return body.get("credential") instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
  }

  private static Response unauthorized() {
    return Response.status(401).type(MediaType.APPLICATION_JSON)
        .entity(Map.of("error", "unauthorized")).build();
  }

  private static Response badRequest(RuntimeException ex) {
    log.warn("WebAuthn ceremony rejected: {}", ex.getMessage());
    return Response.status(400).type(MediaType.APPLICATION_JSON)
        .entity(Map.of("error", "webauthn_failed")).build();
  }

  private static String str(Object o) {
    return o == null ? "" : String.valueOf(o);
  }
}
